import{_ as i,c as n,o as a,a2 as t}from"./chunks/framework.PGES7OoM.js";const d=JSON.parse('{"title":"Listening To Events","description":"","frontmatter":{"rawMarkdown":"# Listening To Events\\n\\nThe SDK emits typed events for its background work — balance scans, plan execution, session health, and account changes. Subscribe with [`on`](/sdk/actions/events/on), which returns an unsubscribe function:\\n\\n```ts\\nimport { CURVY_EVENT_TYPES } from \\"@0xcurvy/curvy-sdk\\";\\nimport { on } from \\"@0xcurvy/curvy-sdk/actions\\";\\n\\nconst unsubscribe = on(CURVY_EVENT_TYPES.BALANCE_REFRESH_PROGRESS, (e) => {\\n  console.log(`Scanning... ${e.progress}%`);\\n});\\n\\n// later:\\nunsubscribe();\\n```\\n\\nThe listener\'s `eventData` is automatically narrowed to the payload type of the event you subscribe to.\\n\\nFor abort-driven cleanup — handy in React effects — pass an `AbortSignal` instead of keeping the unsubscribe function around:\\n\\n```ts\\nconst controller = new AbortController();\\non(CURVY_EVENT_TYPES.BALANCE_REFRESH_COMPLETE, onComplete, { signal: controller.signal });\\n\\n// removes the listener automatically:\\ncontroller.abort();\\n```\\n\\n## Available events\\n\\n| Group | Events |\\n| --- | --- |\\n| Balance refresh | `BALANCE_REFRESH_STARTED`, `BALANCE_REFRESH_PROGRESS`, `BALANCE_REFRESH_COMPLETE`, `BALANCE_REFRESH_CANCELLED`, `BALANCE_REFRESH_ERROR` |\\n| Plan execution | `PLAN_EXECUTION_STARTED`, `PLAN_EXECUTION_PROGRESS`, `PLAN_EXECUTION_COMPLETE`, `PLAN_EXECUTION_ERROR` |\\n| Session | `JWT_REFRESH_SUCCESS`, `JWT_REFRESH_ERROR`, `UNAUTHORIZED` |\\n| Accounts | `ACCOUNT_ADDED`, `ACCOUNT_REMOVED`, `ACCOUNT_CHANGED` |\\n","rawMarkdownPath":"/_raw/for-programmers/listening-to-events.md","rawMarkdownTitle":"Listening To Events","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-programmers/listening-to-events.md"},"headers":[],"relativePath":"for-programmers/listening-to-events.md","filePath":"for-programmers/listening-to-events.md","lastUpdated":1786521734000}'),e={name:"for-programmers/listening-to-events.md"};function l(E,s,o,h,r,p){return a(),n("div",null,[...s[0]||(s[0]=[t("",8)])])}const c=i(e,[["render",l]]);export{d as __pageData,c as default};
